sys_variable_value.value:
(function (outputs, steps, params, stepResult, assertEqual) {

	var bLog = false;
	var _mappingCfgMgr = new x_snc_mapping_cm.MappingConfigManager();
	var _mappingCfgScheduler = new x_snc_mapping_cm.MappingConfigScheduler();
	var _gtATF = new global.GlobalToolsATF('MappingConfigManager', _mappingCfgMgr, bLog, outputs, steps, params, stepResult, assertEqual);
	var _gt = new global.GlobalTools();
	var _gtTable = new global.GlobalToolsTable();
	var grRecord;

	function updateMapping(sMappingId, sTargetValue, sTargetValue2) {
		grMappingCfg = new GlideRecord('x_snc_mapping_cm_mapping_config');
		if (grMappingCfg.get(sMappingId)) {
			grMappingCfg.setValue('target_value', sTargetValue);
			if (sTargetValue2) {
				grMappingCfg.setValue('target_value_2', sTargetValue2);
			} // if target value 2
			grMappingCfg.setValue('apply_job_status', 'approved');
			if (!grMappingCfg.update()) {
				gs.error('tomtom mapping error saving sMappingId: ' + sMappingId + ' sTargetValue: ' + sTargetValue + ' sTargetValue2: ' + sTargetValue2 + ' Error: ' + grMappingCfg.getLastErrorMessage());
			} // if error
		} else {
			gs.error('tomtom mapping not found sMappingId: ' + sMappingId + ' sTargetValue: ' + sTargetValue + ' sTargetValue2: ' + sTargetValue2);
		} // if mapping
		_gt.sleep(10000);
	} // function updateMapping

	var oTestDataConfig = {
		core_company: [
			{
				name: 'atf_company_1',
				sys_id: '10000000000000000000000000000001'
			},
			{
				name: 'atf_manufacturer_1',
				sys_id: '10000000000000000000000000000002'
			}
		], // companies
		business_unit: [
			{
				name: 'atf_bu_1',
				sys_id: '20000000000000000000000000000001',
				company: '10000000000000000000000000000001'
			}
		], // business units
		sys_user: [
			{
				user_name: 'atf_user_1',
				first_name: 'atf',
				last_name: 'user_1',
				sys_id: '30000000000000000000000000000001',
				company: '10000000000000000000000000000001'
			},
			{
				user_name: 'atf_user_2',
				first_name: 'atf',
				last_name: 'user_2',
				sys_id: '30000000000000000000000000000002',
				company: '10000000000000000000000000000001'
			},
			{
				user_name: 'atf_user_3',
				first_name: 'atf',
				last_name: 'user_3',
				sys_id: '30000000000000000000000000000003',
				company: '10000000000000000000000000000001'
			}
		], // users
		cmdb_ci_win_server: [
			{
				name: 'atf_ci_1',
				company: '10000000000000000000000000000091',
				manufacturer: '10000000000000000000000000000092',
				install_status: '55',
				os: 'Windows11',
			},
			{
				name: 'atf_ci_2',
				company: '10000000000000000000000000000091',
				manufacturer: '10000000000000000000000000000092',
				install_status: '55',
				os: 'Windows11',
			},
		], // windows servers
		alm_hardware: [
			{
				asset_tag: 'atf_asset_1',
				company: '10000000000000000000000000000091',
				vendor: '10000000000000000000000000000092',
				install_status: '55',
				substatus: '33',
			},
			{
				asset_tag: 'atf_asset_2',
				company: '10000000000000000000000000000091',
				vendor: '10000000000000000000000000000092',
				install_status: '55',
				substatus: '33',
			},
			{
				asset_tag: 'atf_asset_3',
				company: '10000000000000000000000000000091',
				vendor: '10000000000000000000000000000092',
				install_status: '44',
				substatus: '33',
			},
			{
				asset_tag: 'atf_asset_4',
				company: '10000000000000000000000000000091',
				vendor: '10000000000000000000000000000092',
				install_status: '44',
				substatus: '33',
			},
			{
				asset_tag: 'atf_asset_5',
				company: '10000000000000000000000000000001',
				vendor: '10000000000000000000000000000092',
				install_status: '7',
				substatus: '55',
			},
			{
				asset_tag: 'atf_asset_6',
				company: '10000000000000000000000000000001',
				vendor: '10000000000000000000000000000092',
				install_status: '7',
				substatus: '55',
			},
			{
				asset_tag: 'atf_asset_7',
				company: '10000000000000000000000000000091',
				vendor: '10000000000000000000000000000092',
				install_status: '1',
				substatus: '55',
			},
			{
				asset_tag: 'atf_asset_8',
				company: '10000000000000000000000000000091',
				vendor: '10000000000000000000000000000092',
				install_status: '1',
				substatus: '55',
			},
		], // windows servers
		cmdb_ci_service: [
			{
				name: 'atf_service_1',
				company: '10000000000000000000000000000001',
				number: 'atf_service_1',
				stakeholders: '30000000000000000000000000000091, 30000000000000000000000000000001, 30000000000000000000000000000002, 30000000000000000000000000000092',
			},
			{
				name: 'atf_service_2',
				number: 'atf_service_2',
				company: '10000000000000000000000000000001',
				stakeholders: '30000000000000000000000000000002, 30000000000000000000000000000092, 30000000000000000000000000000091, 30000000000000000000000000000001',
			},
		], // services
	}; // test data setup

	_gtATF.generateTestData(oTestDataConfig, true);

	///
	/// Test invalid input and fields
	/// 

	_gtATF.runATF('doMappingValue', undefined);

	_gtATF.runATF('doMappingValue', undefined, '');
	_gtATF.runATF('doMappingValue', undefined, 'cmdb_ci', '');
	_gtATF.runATF('doMappingValue', 'sugus', '', 'sugus');
	_gtATF.runATF('doMappingValue', 'sugus', 'cmdb_ci', 'sugus');
	_gtATF.runATF('doMappingValue', 'sugus', 'cmdb_ci', 'sugus', 'sugus_disp', 'cmdb_ci_service', 'invalid_field');


	grMapCfgEntry = _gtATF.getRecord('x_snc_mapping_cm_mapping_config', 'type=choice^choice_table=cmdb_ci_service^choice_field=invalid_field^source_value=sugus');
	if (grMapCfgEntry) {
		_gtATF.addError('getMappedValue', 'Generated choice record with invalid field found!');
	} // if invalid entry

	/// 
	/// Field type: Reference
	/// 
	// Test insert mapping
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000091', 'cmdb_ci_win_server', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000091', 'alm_hardware', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000091', 'alm_asset', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000092', 'cmdb_ci_win_server', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000092', 'alm_hardware', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000092', 'alm_asset', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gt.sleep(500);
	// Test get un-mapped value
	_gtATF.runATF('getMappedValue', '10000000000000000000000000000091', '10000000000000000000000000000091', 'core_company');
	_gtATF.runATF('getMappedValue', '10000000000000000000000000000092', '10000000000000000000000000000092', 'core_company');

	// Test affected table and fields
	var grMapCfgEntry = _gtATF.getRecord('x_snc_mapping_cm_mapping_config', 'type=reference^choice_table=core_company^choice_fieldISEMPTY^source_value=10000000000000000000000000000091');
	var sTableIds = '', aTableIds = [], aTableNames = [], sTableNames = '', grMapApplyTables, grFields = [];
	if (grMapCfgEntry) {
		sTableIds = grMapCfgEntry.getValue('parent_tables');
		aTableIds = sTableIds.split(',');
		aTableNames = [];
		aTableIds.forEach(function (sTableId) {
			aTableNames.push(_gtTable.getTableName(sTableId));
		}, this); // each table id
		sTableNames = aTableNames.join(',');
		if (sTableNames == 'cmdb_ci_win_server,alm_hardware,alm_asset') {
			grMapApplyTables = _gtATF.getRecord('x_snc_mapping_cm_affected_table', 'affected_table=cmdb_ci_win_server^choice_table=core_company');
			if (!grMapApplyTables) {
				_gtATF.addError('_mappingCfgMgr', 'Generated reference record affected table do not match. Expected: cmdb_ci_win_server and choice table core_company');
			} // if not affected table
			grMapApplyTables = _gtATF.getRecord('x_snc_mapping_cm_affected_table', 'affected_table=alm_hardware^choice_table=core_company');
			if (!grMapApplyTables) {
				_gtATF.addError('_mappingCfgMgr', 'Generated reference record affected table do not match. Expected: cmdb_ci_win_server and choice table core_company');
			} // if not affected table
			grMapApplyTables = _gtATF.getRecord('x_snc_mapping_cm_affected_table', 'affected_table=alm_asset^choice_table=core_company');
			if (grMapApplyTables) {
				grFields = grMapApplyTables.getValue('sss');
			} else {
				_gtATF.addError('_mappingCfgMgr', 'Generated reference record affected table do not match. Expected: cmdb_ci_win_server and choice table core_company');
			} // if not affected table
		} else {
			_gtATF.addError('_mappingCfgMgr', 'Generated reference record parent tables do not match. Expected: cmdb_ci_win_server,alm_hardware,alm_asset found: ' + sTableNames);
		} // if same order
	} else {
		_gtATF.addError('_mappingCfgMgr', 'Generated reference record with multiple parents not found!');
	} // if mapped entry

	// Test redo un-mapped value
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000091', 'cmdb_ci_win_server', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000091', 'alm_hardware', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000091', 'alm_asset', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000092', 'cmdb_ci_win_server', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000092', 'alm_hardware', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000092', 'alm_asset', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	// Update mapping
	updateMapping(_mappingCfgMgr.getMappedValue('10000000000000000000000000000091', 'core_company', '', '', '', true), '10000000000000000000000000000001', '20000000000000000000000000000001');
	updateMapping(_mappingCfgMgr.getMappedValue('10000000000000000000000000000092', 'core_company', '', '', '', true), '10000000000000000000000000000002');
	// Test get mapped value	
	_gtATF.runATF('getMappedValue', '10000000000000000000000000000001', '10000000000000000000000000000091', 'core_company');
	_gtATF.runATF('getMappedValue', '10000000000000000000000000000002', '10000000000000000000000000000092', 'core_company');
	// Test redo mapped value
	_gtATF.runATF('doMappingValue', /10000000000000000000000000000001/i, 'cmdb_ci_win_server', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', /10000000000000000000000000000001/i, 'alm_hardware', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', /10000000000000000000000000000001/i, 'alm_asset', '10000000000000000000000000000091', 'Company_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000002', 'cmdb_ci_win_server', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000002', 'alm_hardware', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000002', 'alm_asset', '10000000000000000000000000000092', 'Manufacturer_1', 'core_company');
	// Test apply mapping
	grRecord = _gtATF.getRecord('cmdb_ci_win_server', 'company=10000000000000000000000000000091');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "cmdb_ci_win_server" failed. Expected: No records with unmapped company exist in this table (10000000000000000000000000000091)');
	} // if un-mapped company
	grRecord = _gtATF.getRecord('cmdb_ci_win_server', 'manufacturer=10000000000000000000000000000092');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "cmdb_ci_win_server" failed. Expected: No records with unmapped manufacturer exist in this table (10000000000000000000000000000092)');
	} // if un-mapped company

	/// 
	/// Field type: Glide List
	/// 
	// Test insert mapping
	_gtATF.runATF('doMappingValue', '30000000000000000000000000000091', 'cmdb_ci_service', '30000000000000000000000000000091', 'User_91', 'sys_user');
	_gtATF.runATF('doMappingValue', '30000000000000000000000000000092', 'cmdb_ci_service', '30000000000000000000000000000092', 'User_92', 'sys_user');
	_gt.sleep(500);
	// Test get un-mapped value
	_gtATF.runATF('getMappedValue', '30000000000000000000000000000091', '30000000000000000000000000000091', 'sys_user');
	_gtATF.runATF('getMappedValue', '30000000000000000000000000000092', '30000000000000000000000000000092', 'sys_user');
	// Test redo un-mapped value
	_gtATF.runATF('doMappingValue', '30000000000000000000000000000091', 'cmdb_ci_service', '30000000000000000000000000000091', 'User_91', 'sys_user');
	_gtATF.runATF('doMappingValue', '30000000000000000000000000000092', 'cmdb_ci_service', '30000000000000000000000000000092', 'User_92', 'sys_user');
	// Update mapping
	updateMapping(_mappingCfgMgr.getMappedValue('30000000000000000000000000000091', 'sys_user', '', '', '', true), '30000000000000000000000000000001');
	updateMapping(_mappingCfgMgr.getMappedValue('30000000000000000000000000000092', 'sys_user', '', '', '', true), '30000000000000000000000000000003');
	// Test get mapped value	
	_gtATF.runATF('getMappedValue', '30000000000000000000000000000001', '30000000000000000000000000000091', 'sys_user');
	_gtATF.runATF('getMappedValue', '30000000000000000000000000000003', '30000000000000000000000000000092', 'sys_user');
	// Test redo mapped value
	_gtATF.runATF('doMappingValue', '30000000000000000000000000000001', 'cmdb_ci_service', '30000000000000000000000000000091', 'User_91', 'sys_user');
	_gtATF.runATF('doMappingValue', '30000000000000000000000000000003', 'cmdb_ci_service', '30000000000000000000000000000092', 'User_92', 'sys_user');
	// Test apply mapping
	grRecord = _gtATF.getRecord('cmdb_ci_service', 'stakeholders=30000000000000000000000000000091');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "cmdb_ci_service" failed. Expected: No records with unmapped user in field stakeholders exist in this table (30000000000000000000000000000091)');
	} // if un-mapped user
	grRecord = _gtATF.getRecord('cmdb_ci_service', 'stakeholders=30000000000000000000000000000092');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "cmdb_ci_service" failed. Expected: No records with unmapped user in field stakeholders exist in this table (30000000000000000000000000000092)');
	} // if un-mapped user

	/// 
	/// Field type: Choice List
	/// 
	// Test insert mapping
	_gtATF.runATF('doMappingValue', 'Windows11', 'cmdb_ci_computer', 'Windows11', 'Windows 11', 'cmdb_ci_computer', 'os');
	_gtATF.runATF('doMappingValue', '55', 'cmdb_ci', '55', 'New Status', 'cmdb_ci', 'install_status');
	_gt.sleep(500);
	// Test get un-mapped value
	_gtATF.runATF('getMappedValue', 'Windows11', 'Windows11', 'cmdb_ci_computer', 'os');
	_gtATF.runATF('getMappedValue', '55', '55', 'cmdb_ci', 'install_status');
	// Test affected table and fields
	grMapCfgEntry = _gtATF.getRecord('x_snc_mapping_cm_mapping_config', 'type=choice^choice_table=cmdb_ci_computer^choice_field=os^source_value=Windows11');
	if (grMapCfgEntry) {
		sTableIds = grMapCfgEntry.getValue('parent_tables');
		aTableIds = sTableIds.split(',');
		aTableNames = [];
		aTableIds.forEach(function (sTableId) {
			aTableNames.push(_gtTable.getTableName(sTableId));
		}, this); // each table id
		sTableNames = aTableNames.join(',');
		if (sTableNames == 'cmdb_ci_computer') {
			grMapApplyTables = _gtATF.getRecord('x_snc_mapping_cm_affected_table', 'affected_table=cmdb_ci_computer^choice_table=cmdb_ci_computer^choice_field=os');
			if (grMapApplyTables) {
				grFields = grMapApplyTables.getValue('sss');
			} else {
				_gtATF.addError('_mappingCfgMgr', 'Generated choice record affected table do not match. Expected: cmdb_ci_computer and choice table cmdb_ci_computer');
			} // if not affected table
		} else {
			_gtATF.addError('_mappingCfgMgr', 'Generated choice record parent tables do not match. Expected: cmdb_ci_computer found: ' + sTableNames);
		} // if same order
	} else {
		_gtATF.addError('_mappingCfgMgr', 'Generated choice record with multiple parents not found!');
	} // if mapped entry
	// Test redo un-mapped value
	_gtATF.runATF('doMappingValue', 'Windows11', 'cmdb_ci_computer', 'Windows11', 'Windows 11', 'cmdb_ci_computer', 'os');
	_gtATF.runATF('doMappingValue', '55', 'cmdb_ci', '55', 'New Status', 'cmdb_ci', 'install_status');
	// Update mapping
	var grChoice = _gtATF.getRecord('sys_choice', 'name=cmdb_ci_computer^element=os^language=en^value=Windows');
	updateMapping(_mappingCfgMgr.getMappedValue('Windows11', 'cmdb_ci_computer', 'os', '', '', true), grChoice.getUniqueValue());
	grChoice = _gtATF.getRecord('sys_choice', 'name=cmdb_ci^element=install_status^language=en^value=6');
	updateMapping(_mappingCfgMgr.getMappedValue('55', 'cmdb_ci', 'install_status', '', '', true), grChoice.getUniqueValue());
	// Test get mapped value	
	_gtATF.runATF('getMappedValue', 'Windows', 'Windows11', 'cmdb_ci_computer', 'os');
	_gtATF.runATF('getMappedValue', '6', '55', 'cmdb_ci', 'install_status');
	// Test redo mapped value
	_gtATF.runATF('doMappingValue', 'Windows', 'cmdb_ci_computer', 'Windows11', 'Windows 11', 'cmdb_ci_computer', 'os');
	_gtATF.runATF('doMappingValue', '6', 'cmdb_ci', '55', 'New Status', 'cmdb_ci', 'install_status');
	// Test apply mapping
	grRecord = _gtATF.getRecord('cmdb_ci_win_server', 'os=Windows11');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "cmdb_ci_win_server" failed. Expected: No records with unmapped value "Windows11" in field os exist in this table');
	} // if un-mapped choice
	grRecord = _gtATF.getRecord('cmdb_ci_win_server', 'install_status=55');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "cmdb_ci_win_server" failed. Expected: No records with unmapped value "55" in field install_status exist in this table');
	} // if un-mapped choice

	/// 
	/// Field type: Choice List with Dependent Not Exist
	/// 
	// Test insert mapping
	_gtATF.runATF('doMappingValue', '55', 'alm_asset', '55', 'New Status', 'alm_asset', 'install_status');
	_gtATF.runATF('doMappingValue', '33', 'alm_asset', '33', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '55');
	_gtATF.runATF('doMappingValue', '33', 'alm_asset', '33', 'New SubStatus 2', 'alm_asset', 'substatus', 'install_status', '44');
	_gt.sleep(500);
	// Test get un-mapped value
	_gtATF.runATF('getMappedValue', '55', '55', 'alm_asset', 'install_status');
	_gtATF.runATF('getMappedValue', '33', '33', 'alm_asset', 'substatus', 'install_status', '55');
	_gtATF.runATF('getMappedValue', '44', '44', 'alm_asset', 'install_status');
	_gtATF.runATF('getMappedValue', '33', '33', 'alm_asset', 'substatus', 'install_status', '44');
	// Test redo un-mapped value
	_gtATF.runATF('doMappingValue', '55', 'alm_asset', '55', 'New Status', 'alm_asset', 'install_status');
	_gtATF.runATF('doMappingValue', '33', 'alm_asset', '33', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '55');
	_gtATF.runATF('doMappingValue', '33', 'alm_asset', '33', 'New SubStatus 2', 'alm_asset', 'substatus', 'install_status', '44');
	// Update mapping
	grChoice = _gtATF.getRecord('sys_choice', 'name=alm_asset^element=install_status^language=en^value=6');
	updateMapping(_mappingCfgMgr.getMappedValue('55', 'alm_asset', 'install_status', '', '', true), grChoice.getUniqueValue());
	grChoice = _gtATF.getRecord('sys_choice', 'name=alm_asset^element=substatus^language=en^dependent_value=6^value=pending_disposal');
	updateMapping(_mappingCfgMgr.getMappedValue('33', 'alm_asset', 'substatus', 'install_status', '55', true), grChoice.getUniqueValue());
	grChoice = _gtATF.getRecord('sys_choice', 'name=alm_asset^element=install_status^language=en^value=7');
	updateMapping(_mappingCfgMgr.getMappedValue('44', 'alm_asset', 'install_status', '', '', true), grChoice.getUniqueValue());
	grChoice = _gtATF.getRecord('sys_choice', 'name=alm_asset^element=substatus^language=en^dependent_value=7^value=obsolete');
	updateMapping(_mappingCfgMgr.getMappedValue('33', 'alm_asset', 'substatus', 'install_status', '44', true), grChoice.getUniqueValue());
	// Test get mapped value	
	_gtATF.runATF('getMappedValue', '6', '55', 'alm_asset', 'install_status');
	_gtATF.runATF('getMappedValue', 'pending_disposal', '33', 'alm_asset', 'substatus', 'install_status', '55');
	_gtATF.runATF('getMappedValue', '7', '44', 'alm_asset', 'install_status');
	_gtATF.runATF('getMappedValue', 'obsolete', '33', 'alm_asset', 'substatus', 'install_status', '44');
	// Test redo mapped value
	_gtATF.runATF('doMappingValue', '6', 'alm_asset', '55', 'New Status', 'alm_asset', 'install_status');
	_gtATF.runATF('doMappingValue', 'pending_disposal', 'alm_asset', '33', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '55');
	_gtATF.runATF('doMappingValue', 'obsolete', 'alm_asset', '33', 'New SubStatus 2', 'alm_asset', 'substatus', 'install_status', '44');
	// Test apply mapping
	grRecord = _gtATF.getRecord('alm_hardware', 'install_status=55');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "alm_hardware" failed. Expected: No records with unmapped value "55" in field install_status exist in this table');
	} // if un-mapped choice
	grRecord = _gtATF.getRecord('alm_hardware', 'install_status=44');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "alm_hardware" failed. Expected: No records with unmapped value "44" in field install_status exist in this table');
	} // if un-mapped choice
	grRecord = _gtATF.getRecord('alm_hardware', 'substatus=33');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "alm_hardware" failed. Expected: No records with unmapped value "33" in field substatus exist in this table');
	} // if un-mapped choice

	/// 
	/// Field type: Choice List with Dependent Exist
	/// 
	// Test insert mapping
	_gtATF.runATF('doMappingValue', '55', 'alm_asset', '55', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '7');
	_gtATF.runATF('doMappingValue', '55', 'alm_asset', '55', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '1');
	_gt.sleep(500);
	// Test get un-mapped value
	_gtATF.runATF('getMappedValue', '55', '55', 'alm_asset', 'substatus', 'install_status', '7');
	_gtATF.runATF('getMappedValue', '55', '55', 'alm_asset', 'substatus', 'install_status', '1');
	// Test redo un-mapped value
	_gtATF.runATF('doMappingValue', '55', 'alm_asset', '55', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '7');
	_gtATF.runATF('doMappingValue', '55', 'alm_asset', '55', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '1');
	// Update mapping
	grChoice = _gtATF.getRecord('sys_choice', 'name=alm_asset^element=substatus^language=en^dependent_value=7^value=obsolete');
	updateMapping(_mappingCfgMgr.getMappedValue('55', 'alm_asset', 'substatus', 'install_status', '7', true), grChoice.getUniqueValue());
	grChoice = _gtATF.getRecord('sys_choice', 'name=alm_asset^element=substatus^language=en^dependent_value=1^value=end_of_support');
	updateMapping(_mappingCfgMgr.getMappedValue('55', 'alm_asset', 'substatus', 'install_status', '1', true), grChoice.getUniqueValue());
	// Test get mapped value	
	_gtATF.runATF('getMappedValue', 'obsolete', '55', 'alm_asset', 'substatus', 'install_status', '7');
	_gtATF.runATF('getMappedValue', 'end_of_support', '55', 'alm_asset', 'substatus', 'install_status', '1');
	// Test redo mapped value
	_gtATF.runATF('doMappingValue', 'obsolete', 'alm_asset', '55', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '7');
	_gtATF.runATF('doMappingValue', 'end_of_support', 'alm_asset', '55', 'New SubStatus', 'alm_asset', 'substatus', 'install_status', '1');
	// Test apply mapping
	grRecord = _gtATF.getRecord('alm_hardware', 'substatus=55');
	if (grRecord) {
		_gtATF.addError('_mappingCfgMgr', 'Apply mapping on "alm_hardware" failed. Expected: No records with unmapped value "55" in field substatus exist in this table');
	} // if un-mapped choice

	///
	/// Test scheduled cleanup (de-activation of added values that no longer need to be mapped)
	///
	// Test insert mapping
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000093', 'cmdb_ci_win_server', '10000000000000000000000000000093', 'Company_3', 'core_company');
	_gtATF.runATF('doMappingValue', 'Windows99', 'cmdb_ci_computer', 'Windows99', 'Windows 99', 'cmdb_ci_computer', 'os');
	// Add the data
	var oTestDataConfigScheduler = {
		core_company: [
			{
				name: 'atf_company_3',
				sys_id: '10000000000000000000000000000093'
			}
		],
		sys_choice: [
			{
				name: 'cmdb_ci_computer',
				element: 'os',
				language: 'en',
				value: 'Windows99',
				sys_id: '99000000000000000000000000000091'
			}
		],
	}; // add data
	_gtATF.generateTestData(oTestDataConfigScheduler, true);
	_gt.sleep(1000);
	// Run cleanup
	_mappingCfgScheduler._scheduledCleanup();
	// Check inactive
	var sMappingIdRef = _mappingCfgMgr.getMappedValue('10000000000000000000000000000093', 'core_company', '', '', '', true);
	var grMappingCfg = new GlideRecord('x_snc_mapping_cm_mapping_config');
	if (grMappingCfg.get(sMappingIdRef)) {
		if (grMappingCfg.getValue('active') == '1') {
			_gtATF.addError('_mappingCfgMgr', 'De-activating mapping on "core_company" failed. Expected: mapping for value "10000000000000000000000000000093" is de-activated');
		} // if de-activated
	} // if mapping id
	var sMappingIdChoice = _mappingCfgMgr.getMappedValue('Windows99', 'cmdb_ci_computer', 'os', '', '', true);
	grMappingCfg = new GlideRecord('x_snc_mapping_cm_mapping_config');
	if (grMappingCfg.get(sMappingIdChoice)) {
		if (grMappingCfg.getValue('active') == '1') {
			_gtATF.addError('_mappingCfgMgr', 'De-activating mapping on "os" failed. Expected: mapping for value "Windows99" is de-activated');
		} // if de-activated
	} // if mapping id
	// Delete again
	var grCompany = new GlideRecord('core_company');
	if (grCompany.get('10000000000000000000000000000093')) {
		grCompany.deleteRecord();
	} // if delete company
	grChoice = new GlideRecord('sys_choice');
	if (grChoice.get('99000000000000000000000000000091')) {
		grChoice.deleteRecord();
	} // if delete choice
	// Re-activate it
	_gtATF.runATF('doMappingValue', '10000000000000000000000000000093', 'cmdb_ci_win_server', '10000000000000000000000000000093', 'Company_3', 'core_company');
	grMappingCfg = new GlideRecord('x_snc_mapping_cm_mapping_config');
	if (grMappingCfg.get(sMappingIdRef)) {
		if (grMappingCfg.getValue('active') == '0') {
			_gtATF.addError('_mappingCfgMgr', 'Re-activating mapping on "core_company" failed. Expected: mapping for value "10000000000000000000000000000093" is active');
		} // if de-activated
	} // if mapping id
	grMappingCfg = new GlideRecord('x_snc_mapping_cm_mapping_config');
	if (grMappingCfg.get(sMappingIdChoice)) {
		if (grMappingCfg.getValue('active') == '1') {
			_gtATF.addError('_mappingCfgMgr', 'Re-activating mapping on "os" failed. Expected: mapping for value "Windows99" is active');
		} // if de-activated
	} // if mapping id
	//gs.error('tomtom oTestDataConfig: ' + JSON.stringify(oTestDataConfig));

	//_gt.sleep(60000);

	return _gtATF.endATF();

})(outputs, steps, params, stepResult, assertEqual);
